# Python 特殊處理：整數是無限位元，要手動遮罩成 32 位元
class Solution:
    def getSum(self, a: int, b: int) -> int:
        MASK = 0xFFFFFFFF        # 32 位元遮罩
        MAX_INT = 0x7FFFFFFF     # 32 位元有號數最大值

        a &= MASK
        b &= MASK
        while b:
            carry = ((a & b) << 1) & MASK   # 進位
            a = (a ^ b) & MASK              # 無進位和
            b = carry

        # 若超過 MAX_INT，代表是負數，轉回 Python 的負數表示
        return a if a <= MAX_INT else ~(a ^ MASK)


# 遞迴版本
class Solution:
    def getSum(self, a: int, b: int) -> int:
        MASK = 0xFFFFFFFF
        MAX_INT = 0x7FFFFFFF
        if b == 0:
            return a if a <= MAX_INT else ~(a ^ MASK)
        return self.getSum((a ^ b) & MASK, ((a & b) << 1) & MASK)

