// 迭代版（C++ 不需特殊處理負數）
class Solution {
public:
    int getSum(int a, int b) {
        while (b != 0) {
            // 用 unsigned 避免有號數左移的 UB
            unsigned int carry = (unsigned int)(a & b) << 1;
            a = a ^ b;      // 無進位和
            b = carry;      // 進位
        }
        return a;
    }
};

// 遞迴版
class Solution {
public:
    int getSum(int a, int b) {
        if (b == 0) return a;
        return getSum(a ^ b, (unsigned int)(a & b) << 1);
    }
};

// 延伸：不用 - 做減法（a - b = a + (-b) = a + ~b + 1）
int getSub(int a, int b) {
    return getSum(a, getSum(~b, 1));
}

