// 迭代版（推薦）
class Solution {
    public int getSum(int a, int b) {
        while (b != 0) {
            int carry = (a & b) << 1;   // 進位
            a = a ^ b;                  // 無進位和
            b = carry;
        }
        return a;
    }
}

// 遞迴版
class Solution {
    public int getSum(int a, int b) {
        return b == 0 ? a : getSum(a ^ b, (a & b) << 1);
    }
}

