// XOR 是不進位加法，(a & b) << 1 是進位，重複到沒有進位為止
// 進位用 unsigned 計算，避免有號數左移溢位的未定義行為
// 時間複雜度: O(32)，空間複雜度: O(1)
int getSum(int a, int b) {
    while (b != 0) {
        unsigned int carry = ((unsigned int)(a & b)) << 1;
        a = a ^ b;
        b = (int)carry;
    }
    return a;
}
